import {
  OPTION_SPECS,
  formatExpectedOneArgument,
  formatMissingRequired,
  formatUnrecognized,
  getHelp,
  getProgramName,
} from "./spec.mjs";

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const OPTION_BY_FLAG = new Map(OPTION_SPECS.map((option) => [option.flag, option]));

function isOptionLikeToken(token) {
  if (!token || token === "-") {
    return false;
  }

  if (NEGATIVE_NUMBER_PATTERN.test(token)) {
    return false;
  }

  return token.startsWith("-");
}

function findAssignedOption(token) {
  for (const option of OPTION_SPECS) {
    if (token.startsWith(`${option.flag}=`)) {
      return option;
    }
  }
  return null;
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv[1]);
  const tokens = argv.slice(2);
  const values = {};
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === "--") {
      extras.push(...tokens.slice(index));
      break;
    }

    if (token === "-h" || token === "--help") {
      return {
        kind: "help",
        code: 0,
        text: `${getHelp(programName)}\n`,
      };
    }

    const directOption = OPTION_BY_FLAG.get(token);
    if (directOption) {
      const nextToken = tokens[index + 1];
      if (
        nextToken === undefined ||
        nextToken === "--" ||
        isOptionLikeToken(nextToken)
      ) {
        return {
          kind: "error",
          code: 2,
          text: formatExpectedOneArgument(programName, directOption.flag),
        };
      }

      values[directOption.key] = nextToken;
      index += 1;
      continue;
    }

    const assignedOption = findAssignedOption(token);
    if (assignedOption) {
      values[assignedOption.key] = token.slice(assignedOption.flag.length + 1);
      continue;
    }

    extras.push(token);
  }

  const missingFlags = OPTION_SPECS
    .filter(({ key }) => !(key in values))
    .map(({ flag }) => flag);

  if (missingFlags.length > 0) {
    return {
      kind: "error",
      code: 2,
      text: formatMissingRequired(programName, missingFlags),
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      code: 2,
      text: formatUnrecognized(programName, extras),
    };
  }

  return {
    kind: "ok",
    code: 0,
    values,
  };
}

import { bytesToHex, encodeUtf8, int32be, xorInto } from './encoding.mjs';
import { hmacSha1, SHA1_DIGEST_LENGTH } from './hmac.mjs';

export const DEFAULT_ITERATIONS = 1000;
export const DEFAULT_KEY_LENGTH = 16;

export function derivePbkdf2Key(
  password,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  const passwordBytes = encodeUtf8(password);
  const saltBytes = encodeUtf8(salt);
  const blockCount = Math.ceil(keyLength / SHA1_DIGEST_LENGTH);
  const derivedKey = Buffer.alloc(blockCount * SHA1_DIGEST_LENGTH);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    const initialBlock = Buffer.concat([saltBytes, int32be(blockIndex)]);
    let u = hmacSha1(passwordBytes, initialBlock);
    const accumulator = Buffer.from(u);

    for (let iteration = 1; iteration < iterations; iteration += 1) {
      u = hmacSha1(passwordBytes, u);
      xorInto(accumulator, u);
    }

    accumulator.copy(derivedKey, (blockIndex - 1) * SHA1_DIGEST_LENGTH);
  }

  return derivedKey.subarray(0, keyLength);
}

export function derivePbkdf2Hex(
  password,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  return bytesToHex(derivePbkdf2Key(password, salt, keyLength, iterations));
}

function leftRotate(value, count) {
  return ((value << count) | (value >>> (32 - count))) >>> 0;
}

function readUint32BE(bytes, offset) {
  return (
    (bytes[offset] << 24) |
    (bytes[offset + 1] << 16) |
    (bytes[offset + 2] << 8) |
    bytes[offset + 3]
  ) >>> 0;
}

function writeUint32BE(bytes, offset, value) {
  bytes[offset] = (value >>> 24) & 0xff;
  bytes[offset + 1] = (value >>> 16) & 0xff;
  bytes[offset + 2] = (value >>> 8) & 0xff;
  bytes[offset + 3] = value & 0xff;
}

function padMessage(message) {
  const messageLength = message.length;
  const remainder = (messageLength + 1) % 64;
  const zeroPaddingLength = remainder <= 56 ? 56 - remainder : 120 - remainder;
  const padded = new Uint8Array(messageLength + 1 + zeroPaddingLength + 8);

  padded.set(message, 0);
  padded[messageLength] = 0x80;

  const bitLength = BigInt(messageLength) * 8n;
  for (let index = 0; index < 8; index += 1) {
    padded[padded.length - 1 - index] = Number((bitLength >> BigInt(index * 8)) & 0xffn);
  }

  return padded;
}

export function sha1(message) {
  const padded = padMessage(message);
  const words = new Uint32Array(80);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let chunkOffset = 0; chunkOffset < padded.length; chunkOffset += 64) {
    for (let index = 0; index < 16; index += 1) {
      words[index] = readUint32BE(padded, chunkOffset + index * 4);
    }
    for (let index = 16; index < 80; index += 1) {
      words[index] = leftRotate(
        words[index - 3] ^ words[index - 8] ^ words[index - 14] ^ words[index - 16],
        1,
      );
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let index = 0; index < 80; index += 1) {
      let f;
      let k;

      if (index < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (index < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (index < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      const temp = (leftRotate(a, 5) + f + e + k + words[index]) >>> 0;
      e = d;
      d = c;
      c = leftRotate(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const digest = new Uint8Array(20);
  writeUint32BE(digest, 0, h0);
  writeUint32BE(digest, 4, h1);
  writeUint32BE(digest, 8, h2);
  writeUint32BE(digest, 12, h3);
  writeUint32BE(digest, 16, h4);
  return digest;
}

