export function deriveBlock(passwordBytes, saltBytes, iterations, blockIndex) {
  let value = hmacSha1(passwordBytes, concatBytes(saltBytes, int32be(blockIndex)));
  const output = new Uint8Array(value);

  for (let round = 1; round < iterations; round += 1) {
    value = hmacSha1(passwordBytes, value);
    xorBytes(output, value);
  }

  return output;
}

export class PBKDF2 {
  constructor(password, salt, iterations = 1000) {
    this.passwordBytes = utf8Encode(password);
    this.saltBytes = utf8Encode(salt);
    this.iterations = iterations;
    this.blockIndex = 1;
    this.buffer = new Uint8Array(0);
    this.bufferOffset = 0;
  }

  read(length) {
    if (!Number.isInteger(length) || length < 0) {
      throw new TypeError("length must be a non-negative integer");
    }

    const output = new Uint8Array(length);
    let outputOffset = 0;

    while (outputOffset < length) {
      if (this.bufferOffset === this.buffer.length) {
        this.buffer = deriveBlock(
          this.passwordBytes,
          this.saltBytes,
          this.iterations,
          this.blockIndex,
        );
        this.blockIndex += 1;
        this.bufferOffset = 0;
      }

      const available = this.buffer.length - this.bufferOffset;
      const remaining = length - outputOffset;
      const chunkLength = available < remaining ? available : remaining;

      output.set(
        this.buffer.subarray(this.bufferOffset, this.bufferOffset + chunkLength),
        outputOffset,
      );
      this.bufferOffset += chunkLength;
      outputOffset += chunkLength;
    }

    return output;
  }
}

export function deriveKey(password, salt, length, iterations = 1000) {
  return new PBKDF2(password, salt, iterations).read(length);
