export class CliParseExit extends Error {
  constructor(code, stream, text) {
    super(text);
    this.code = code;
    this.stream = stream;
    this.text = text;
  }
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D\n`;
}

function buildHelp(programName) {
  return (
    `${buildUsage(programName)}\n` +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n' +
    '  --d D\n'
  );
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

function isValueToken(token) {
  return token === '-' || !token.startsWith('-') || NEGATIVE_NUMBER_PATTERN.test(token);
}

function exitWithHelp(programName) {
  throw new CliParseExit(0, 'stdout', buildHelp(programName));
}

function exitWithError(programName, message) {
  throw new CliParseExit(2, 'stderr', buildError(programName, message));
}

export function parseTest6Args(argv = process.argv) {
  const tokens = argv.slice(2);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
    d: undefined,
  };
  const unknown = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--') {
      unknown.push(...tokens.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '--help') {
      exitWithHelp(PROGRAM_NAME);
    }

    const equalsIndex = token.indexOf('=');
    if (equalsIndex !== -1) {
      const flag = token.slice(0, equalsIndex);
      if (OPTION_KEYS_BY_FLAG.has(flag)) {
        values[OPTION_KEYS_BY_FLAG.get(flag)] = token.slice(equalsIndex + 1);
      } else {
        unknown.push(token);
      }
      continue;
    }

    if (OPTION_KEYS_BY_FLAG.has(token)) {
      const nextToken = tokens[index + 1];

      if (nextToken === undefined || !isValueToken(nextToken)) {
        exitWithError(PROGRAM_NAME, `argument ${token}: expected one argument`);
      }

      values[OPTION_KEYS_BY_FLAG.get(token)] = nextToken;
      index += 1;
      continue;
    }

    unknown.push(token);
  }

  const missing = OPTION_DEFINITIONS
    .filter(({ key }) => values[key] === undefined)
    .map(({ flag }) => flag);

  if (missing.length > 0) {
    exitWithError(
      PROGRAM_NAME,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (unknown.length > 0) {
    exitWithError(PROGRAM_NAME, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return values;
}

